use std::hint::black_box as bb;
fn sieve(n: usize) -> Vec<usize> { let mut p = vec![true; n + 1]; p[0] = false; if n >= 1 { p[1] = false; } let mut i = 2; while i * i <= n { if p[i] { let mut j = i * i; while j <= n { p[j] = false; j += i; } } i += 1; } (0..=n).filter(|&i| p[i]).collect() }
fn collatz(mut n: u64) -> u32 { let mut s = 0; while n != 1 { n = if n % 2 == 0 { n / 2 } else { 3 * n + 1 }; s += 1; } s }
fn matmul(a: &[[i64; 3]; 3], b: &[[i64; 3]; 3]) -> [[i64; 3]; 3] { let mut c = [[0; 3]; 3]; for i in 0..3 { for j in 0..3 { for k in 0..3 { c[i][j] += a[i][k] * b[k][j]; } } } c }
fn quicksort<T: PartialOrd + Copy>(v: &mut [T]) { if v.len() <= 1 { return; } let p = v[v.len() / 2]; let (mut i, mut j) = (0, v.len() - 1); loop { while v[i] < p { i += 1; } while v[j] > p { j -= 1; } if i >= j { break; } v.swap(i, j); i += 1; j -= 1; } let (l, r) = v.split_at_mut(i); quicksort(l); quicksort(r); }
fn queens(n: usize, row: usize, cols: &mut Vec<usize>) -> u32 { if row == n { return 1; } let mut c = 0; for col in 0..n { if cols.iter().enumerate().all(|(r, &cc)| cc != col && (row - r) as isize != (col as isize - cc as isize).abs()) { cols.push(col); c += queens(n, row + 1, cols); cols.pop(); } } c }
fn lcg(seed: &mut u64) -> u64 { *seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407); *seed >> 33 }
fn fnv(data: &[u8]) -> u32 { data.iter().fold(2166136261u32, |h, &b| (h ^ b as u32).wrapping_mul(16777619)) }
fn hanoi(n: u32, from: u8, to: u8, via: u8, moves: &mut Vec<(u8, u8)>) { if n == 0 { return; } hanoi(n - 1, from, via, to, moves); moves.push((from, to)); hanoi(n - 1, via, to, from, moves); }
fn edit_distance(a: &str, b: &str) -> usize { let (a, b): (Vec<char>, Vec<char>) = (a.chars().collect(), b.chars().collect()); let mut d: Vec<usize> = (0..=b.len()).collect(); for i in 1..=a.len() { let mut prev = d[0]; d[0] = i; for j in 1..=b.len() { let t = d[j]; d[j] = (d[j] + 1).min(d[j - 1] + 1).min(prev + (a[i - 1] != b[j - 1]) as usize); prev = t; } } d[b.len()] }
